void read_input(int *n, int array[]) {
    scanf("%d", n);
    for (int p = 0; p < *n; p++) {
        scanf("%d", &array[p]);
    }
}

long long compute_sum(int array[], int n) {
    long long answer = 0;
    for (int q = n - 1; q >= 0; q--) {
        answer += array[q];
    }
    return answer;
}

void print_result(long long answer) {
    printf("%lld\n", answer);
}

int main() {
    int n;
    int array[100000];
    read_input(&n, array);
    long long result = compute_sum(array, n);
    print_result(result);
    return 0;
}
